/**
 * Escaping, and the URL allowlist.
 *
 * The whole site is generated by string concatenation, which is the classic way
 * to build an XSS hole. The rule that makes it safe is narrow and absolute:
 * every value that did not originate as a literal in this repository's build
 * code goes through `esc` or `attr` on its way into the output, and nothing
 * emits HTML it did not itself write.
 *
 * There is deliberately no `raw()` escape hatch. If one existed it would get
 * used, and then the rule above would need a caveat, and a rule with a caveat
 * is not a rule. Markdown that contains raw HTML has that HTML dropped rather
 * than passed through -- see markdown.mjs.
 */

/** Text destined for element content. */
export function esc(value) {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

/**
 * Text destined for a double-quoted attribute value.
 *
 * Same as `esc` today. It is a separate function because the two contexts have
 * different rules and conflating them is how the next person introduces a bug:
 * an attribute value also has to survive being read as a URL, an event handler
 * name, or a style, and if that ever needs stricter handling this is where it
 * goes.
 */
export function attr(value) {
  return esc(value);
}

/**
 * Schemes a link may use.
 *
 * An allowlist, not a blocklist. `javascript:` is the obvious one to exclude,
 * but blocklists lose to `java\tscript:`, `JaVaScRiPt:`, `javascript:` and
 * whatever the next parser differential turns out to be. Anything not on this
 * list becomes a plain text node.
 */
const SAFE_SCHEMES = new Set(['http:', 'https:', 'mailto:']);

/**
 * Return `url` if it is safe to put in an href, otherwise null.
 *
 * Relative URLs, absolute paths and fragments are safe by construction: they
 * cannot carry a scheme, so they cannot carry `javascript:`. Everything else
 * must parse as a URL with a scheme on the list.
 */
export function safeUrl(url) {
  const raw = String(url).trim();
  if (!raw) return null;

  // Control characters are stripped by parsers in ways that differ between
  // browsers, which is exactly the sort of disagreement a scheme check should
  // not have to survive. Reject rather than normalise.
  if (/[\u0000-\u001f]/.test(raw)) return null;

  // `//evil.com` is a scheme-relative URL: it looks like a path and navigates
  // off-site. Nothing here needs one, so require an explicit scheme instead.
  //
  // Browsers also treat a backslash as a forward slash in the authority
  // position, so `/\evil.com`, `\\evil.com` and `/\/evil.com` are all the same
  // trick wearing a different character. Normalise before testing rather than
  // enumerating the variants.
  if (/^[\\/]{2}/.test(raw.replace(/\\/g, '/'))) return null;

  if (raw.startsWith('#') || raw.startsWith('/') || raw.startsWith('./') || raw.startsWith('../')) {
    return raw;
  }

  // A bare relative path like `docs/privacy.md`. It has no scheme unless it
  // contains a colon before the first slash, which the parse below catches.
  if (!/^[a-zA-Z][a-zA-Z0-9+.-]*:/.test(raw)) return raw;

  let parsed;
  try {
    parsed = new URL(raw);
  } catch {
    return null;
  }
  return SAFE_SCHEMES.has(parsed.protocol) ? raw : null;
}

/** Join class names, dropping falsy ones. */
export function cls(...names) {
  return names.filter(Boolean).join(' ');
}

/**
 * "A", "A and B", "A, B and C".
 *
 * For lists that are generated from the repository but have to read as a
 * sentence. The alternative — writing the names into the prose — is how the
 * page came to say every agent fails open long after three of them stopped.
 */
export function list(names) {
  const xs = names.filter(Boolean);
  if (xs.length <= 1) return xs[0] ?? '';
  return `${xs.slice(0, -1).join(', ')} and ${xs[xs.length - 1]}`;
}

/**
 * An external link.
 *
 * `rel="noopener"` because a page opened with `target="_blank"` can otherwise
 * reach back through `window.opener` and navigate this one. Modern browsers
 * imply it, older ones do not, and it costs nothing. `noreferrer` keeps the
 * path a reader took off this site out of other people's logs.
 */
export function external(href, text, extra = '') {
  const safe = safeUrl(href);
  if (!safe) return esc(text);
  return `<a href="${attr(safe)}" rel="noopener noreferrer"${extra ? ' ' + extra : ''}>${esc(text)}</a>`;
}
